import sys, random
sys.path.insert(0,'/workspace/submission')
from treap import Priors, fat_insert, fat_pop, fat_charge_less, fat_lag, fat_pairs, lean_insert, lean_extract_min, lean_extract_max, lean_delete, lean_recs

# COW semantics: snapshots must be immutable under later mutation, restores exact.
def cow_test(seed=0, n=300):
    rng = random.Random(seed); pr=Priors()
    root=None; model={}; ver=0; snaps={}
    keys=[(rng.randint(0,9), i) for i in range(n)]
    for i,k in enumerate(keys):
        if rng.random()<0.3 and snaps:
            name=rng.choice(list(snaps))
            root, m, v = snaps[name]
            root=root; model=dict(m); ver=v
        elif rng.random()<0.2:
            ver+=1; snaps[len(snaps)]=(root, dict(model), ver)
        else:
            if rng.random()<0.25 and model:
                key=rng.choice(list(model))
                root,_=fat_pop(root,key,ver,0); model.pop(key)
            elif rng.random()<0.35 and model:
                thr=rng.randint(0,9); root,c=fat_charge_less(root,(thr,0),ver)
                ec=sum(1 for k in model if k[0]<thr)
                assert c==ec,(seed,i,c,ec)
                for kk in list(model):
                    if kk[0]<thr: model[kk]+=1
            else:
                root=fat_insert(root,k,('r',k),pr.take(),ver); model[k]=0
        pairs=[]; fat_pairs(root,0,pairs); got={p[1]:l for p,l in pairs}
        assert got==model,(seed,i,got,model)
    # verify all snapshots still intact
    for name,(r,m,v) in snaps.items():
        pairs=[]; fat_pairs(r,0,pairs); got={p[1]:l for p,l in pairs}
        assert got==m,(seed,'snap',name,got,m)
    return True
for s in range(40): cow_test(s)
print('fat COW snapshot semantics: ok')

def lean_cow_test(seed=0, n=300):
    rng=random.Random(seed); pr=Priors(); root=None; model=[]; ver=0; snaps={}
    for i in range(n):
        r=rng.random()
        if r<0.25 and snaps:
            nm=rng.choice(list(snaps)); root, m, ver = snaps[nm]; model=list(m)
        elif r<0.35:
            ver+=1; snaps[len(snaps)]=(root,list(model),ver)
        elif r<0.5 and model:
            root,node=lean_extract_min(root,ver); model.remove(node[0])
        elif r<0.6 and model:
            root,node=lean_extract_max(root,ver); model.remove(node[0])
        elif r<0.7 and model:
            key=rng.choice(model); root=lean_delete(root,key,ver); model.remove(key)
        else:
            k=(rng.randint(0,9), i)
            if k in model: continue
            root=lean_insert(root,k,('r',k),pr.take(),ver); model.append(k)
        out=[]; lean_recs(root,out)
        assert [x[0] for x in out]==sorted(model), (seed,i)
    for nm,(r,m,v) in snaps.items():
        out=[]; lean_recs(r,out); assert [x[0] for x in out]==sorted(m), (seed,'snap',nm)
    return True
for s in range(40): lean_cow_test(s)
print('lean COW snapshot semantics: ok')
